# -*- coding: utf-8 -*-
"""فصل ۷ (دهکده‌ی جهانی + چهار عصر) و فصل ۸ (تتراد + شکل/زمینه + محیط نامرئی)."""

def ch7(D):
    D.h1("نظریه‌ی ۵: دهکده‌ی جهانی و چهار عصر رسانه", num="۷")

    D.h2("۷.۱. دهکده‌ی جهانی (Global Village)")
    D.quote("We live in a global village where all the world's problems are our own problems.",
            "معنا: در دهکده‌ای جهانی زندگی می‌کنیم که در آن همه‌ی مشکلات جهان، مشکلاتِ خودِ ماست.",
            cite="مک‌لوهان، کهکشان گوتنبرگ، 1962")
    D.para("«دهکده‌ی جهانی»، معروف‌ترین و در عین حال پرتفسیرترین مفهوم مک‌لوهان است. معنا: فناوری‌های الکترونیکی (تلگراف، رادیو، تلویزیون، ماهواره، و بعد از آن اینترنت) «فاصله و زمان» را از بین می‌برند و جهان را به «روستایی» شبیه‌سازی‌شده بازمی‌گردانند که در آن همه‌چیز «هم‌زمان» می‌شود. این «هم‌زمانی»، دو اثر دارد:")
    D.bullet("اثر مثبت: «بازگشت به انگیزش قبیله‌ای» (tribal involvement) — حس تعلق جمعی و مشارکت ادراکی تجمعی تقویت می‌شود (بازگشت به دوران پیش از کتابت).")
    D.bullet("اثر منفی: «حساسیت روانی» بالا می‌رود — ما به همه‌چیز واکنش نشان می‌دهیم، «فرافکنی» (projection) می‌کنیم، و «وضعیت‌های اسپاستیک» (spastic situations — بحران‌های پراکنده و هم‌زمان) پدید می‌آیند.")

    D.h3("۷.۱.۱. آیا دهکده‌ی جهانی، «جهانی‌شدن» (globalization) است؟")
    D.para("خیر، و این نکته را باید روشن کرد. «جهانی‌شدن» (globalization) اصطلاحی «اقتصادی-سیاسی» است (آزادسازی تجارت، شرکت‌های چندملیتی، یکسان‌سازی بازارها). اما «دهکده‌ی جهانی» یک مفهوم «ادراکی-روان‌شناختی» است: به «احساس» فشرده شدن فاصله و هم‌زمانیِ تجربه‌ی انسانی اشاره دارد، نه به ساختارِ اقتصادی. مک‌لوهان می‌گفت دهکده‌ی جهانی، «هم‌گونی و آرامش» نمی‌آورد؛ بلکه «حداکثر اختلاف و گفتگوی خلاقانه» (maximum disagreement and creative dialog) را اجباری می‌کند — «تنش و هم‌زیستی» (conflict and harmony)، همان «لایه‌ی عادی زندگیِ قبیله‌ای» است.")

    D.h3("۷.۱.۲. پیش‌بینیِ ۱۹۶۰ در ۲۰۲۶")
    D.para("مک‌لوهان دهکده‌ی جهانی را در ۱۹۶۲ — یعنی حدود ۳۰ سال پیش از اختراع شبکه‌ی جهانی وب — توصیف کرد. اینترنت و شبکه‌های اجتماعی، دقیقاً همان «دهکده‌ای» را که او توصیف کرده بود، به واقعیت تبدیل کردند: هم‌زمانیِ جهانی، مشارکت ادراکی تجمعی، و بحران‌های پراکنده و هم‌زمان (spastic situations). این «پیش‌بینی»، بخش زیادی از اعتبارِ ماندگار مک‌لوهان را توضیح می‌دهد — و در عین حال، بخش بزرگی از «اسطوره‌سازی» به‌دور از او را نیز.")

    D.h2("۷.۲. چهار عصر رسانه و بازگشت به تیره‌ای")
    D.para("مک‌لوهان تاریخ بشر را به چهار «عصر رسانه‌ای» تقسیم می‌کند — چارچوبی‌ای که ریشه در اینیس و در تاریخ‌نگاری کلاسیک دارد:")
    D.table(
        headers=["عصر", "رسانه‌ی غالب", "شکل ادراک", "ساختار اجتماعی"],
        rows=[
            ["۱. شفاهی / تیره‌ای (Tribal)", "گفتار و افسانه", "لامسه / هم‌زمان / تجمعی", "دایره‌ای، مشارکتی، «تنها شنوایی»"],
            ["۲. خطی / سنگی (Lithic)", "خط و سنگ‌نگاری", "بصری + لامسه (ترکیب)", "خطی-دایره‌ای، سلسله‌مراتبی اولیه"],
            ["۳. گوتنبرگی / چاپی (Gutenberg)", "چاپ متحرک", "بصری / خطی / فردگرا", "مردم‌سالاری فردگرا، ملیت، کارخانه"],
            ["۴. الکترونیکی (Electronic)", "برق، تلگراف، تلویزیون", "لامسه / هم‌زمان / تجمعی (بازگشت)", "دهکده‌ی جهانی، شبکه‌ای، تبریزالیزه‌شده"],
        ],
        col_widths=[4, 3.5, 4, 4.5],
    )
    D.para("نکته‌ی کلیدی: عصر الکترونیکی، «بازگشت» به حالت تیره‌ای (oral-tribal) است، اما در مقیاس «جهانی». این «تبریزالیزه‌شدنِ مجدد» (re-tribalization)، هم «مشارکت تجمعی» را برمی‌گرداند و هم «حساسیت و بحران» را — و این دو وجه با هم، «دهکده‌ی جهانی» را می‌سازند.")

    D.h3("۷.۲.۱. انسان تایپوگرافیک (Typographic Man)")
    D.para("مک‌لوهان، «انسانِ عصر چاپ» را «انسان تایپوگرافیک» می‌نامد. خط چاپ (محرک، از ۱۴۵۰ میلادی به بعد)، ادراک غرب را «بصری، خطی، توالی‌دار و فردگرا» ساخت. این «انسان تایپوگرافیک»، همان کسی‌ای است که «منطقی، خطی، و مبتنی بر فرد» فکر می‌کند — و «ملیت»، «کارخانه»، و «دموکراسی فردگرا» از محصولات همین ادراک‌اند. رسانه‌های الکترونیکی، این «انسان تایپوگرافیک» را «تبریزالیزه» و دوباره «لامسه‌ای» می‌کنند.")
    D.callout("تمرین ۷:", "اینترنت و شبکه‌های اجتماعی را در چارچوب «چهار عصر» قرار دهید: کدام عصر را «بازیابی» (retrieve) و کدام را «منسوخ» (obsolete) می‌کنند؟ (راهنما: اینترنت، هم‌زمانیِ «تیره‌ای» را بازیابی و «خطی‌بودنِ» چاپ را منسوخ می‌کند — اما «فردی‌بودنِ» چاپ را هم به‌شکل جدیدی بازتولید می‌کند.)")
    
    D.h3('۷.۱.۳. سه وجه دهکده‌ی جهانی')
    D.para('مفهوم «دهکده‌ی جهانی» را باید در «سه وجه» فهمید، نه به‌شکل یک «جمله»:')
    D.bullet('وجه ادراکی: «احساس» فشرده‌شدن فاصله و هم‌زمانیِ تجربه. وقتی «خبر» از دورترین نقطه‌ی جهان را «هم‌زمان» با نزدیک‌ترین نقطه می‌بینید، «دهکده‌ی جهانی» را «احساس» می‌کنید.')
    D.bullet('وجه مشارکتی: «مشارکت ادراکی تجمعی» — همه‌ی ما، در یک «حوض اطلاعات» جهانی، «هم‌زمان» درگیر می‌شویم. این «مشارکت»، «تبریزالیزه‌شدن» را می‌سازد.')
    D.bullet('وجه بحرانی: «حساسیت روانی» و «وضعیت‌های اسپاستیک» — «هم‌زمانی»، «واکنش‌های» هم‌زمان و پراکنده می‌سازد (مثل «بحران‌های مالی» یا «ویروس‌های اطلاعاتی»).')
    D.para('این «سه وجه»، نشان می‌دهند که «دهکده‌ی جهانی»، یک «مفهوم تک‌بُعدی» نیست؛ بلکه یک «چارچوب سه‌بُعدی» است که «ادراک، مشارکت و بحران» را هم‌زمان توضیح می‌دهد.')
    D.page_break()


def ch8(D):
    D.h1("نظریه‌ی ۶: تتراد، شکل/زمینه، و محیط نامرئی", num="۸")

    D.h2("۸.۱. تتراد اثرات رسانه (Tetrad of Media Effects)")
    D.para("«تتراد»، کاربردی‌ترین ابزار تحلیلی مک‌لوهان است — ابزاری‌ای که می‌توان آن را روی هر رسانه و فناوری به‌کار برد. چهار پرسش (که هم‌زمان، نه سری، باید طرح شوند):")
    D.bullet("۱. این رسانه چه چیزی را «بهبود/تقویت» (enhance) می‌کند؟")
    D.bullet("۲. چه چیزی را «فرسوده/منسوخ» (obsolete) می‌کند؟")
    D.bullet("۳. چه چیزی را از گذشته «بازیابی» (retrieve) می‌کند؟")
    D.bullet("۴. وقتی به «حد اوج» برسد، به چه چیزی «وارونه/معکوس» (reverse) می‌شود؟")

    D.h3("۸.۱.۱. تتراد به‌عنوان «ریتم»، نه «فهرست»")
    D.para("نکته‌ی اصلی: چهارگانه، یک «فهرست» نیست؛ یک «ریتم» است. هر رسانه در یک لحظه، هر چهار حرکت را «هم‌زمان» انجام می‌دهد. این «هم‌زمانی»، آنچه تتراد را به یک «ابزار» بدل می‌کند، نه یک «توضیح»، مشخص می‌کند. شکل کتابیِ تتراد در Laws of Media (1988، با اریک) است؛ اما ظهور نخستین چاپی آن در مقالات Technology and Culture (1975) و et cetera (1977) بوده است.")

    D.h3("۸.۱.۲. مثال: اتومبیل")
    D.para("مک‌لوهان خود، اتومبیل را «عروس مکانیکی» (mechanical bride) خواند. تترادِ اتومبیل:")
    D.bullet("بهبود (enhance): سرعت، دایره‌ی جغرافیایی زندگی، «گسترشِ پا».")
    D.bullet("منسوخ (obsolete): اسب، جفت‌اسب، و «مکان‌یابیِ محلی» (local presence).")
    D.bullet("بازیابی (retrieve): «قافله» (caravan) — سفرِ جمعی و هم‌جهت (اتومبیل، قافله‌ی قبیله‌ای را در مقیاس جدید باز می‌آورد).")
    D.bullet("وارونگی (reverse): در حد اوج، اتومبیل به «جنگل‌بندان» (gridlock)، «تلخ‌کشی» (racing) و «تروریسمِ جاده‌ای» می‌رسد — وارونگیِ آزادیِ حرکت.")

    D.h3("۸.۱.۳. تمرین کاربردی: تلفن هوشمند")
    D.table(
        headers=["پرسش تتراد", "پاسخ برای تلفن هوشمند"],
        rows=[
            ["بهبود (enhance)", "حافظه، توجه، ارتباط، «گسترشِ سیستم عصبی» در جیب"],
            ["منسوخ (obsolete)", "تلفن ثابت، دستگاه پیامک، ساعت، نقشه، دوربین فیزیکی، آینه (با سلفی)"],
            ["بازیابی (retrieve)", "صدا (تلفنِ کلاسیک) و «حلقه‌ی شفاهی» (گروه‌های چت، ویدیو)"],
            ["وارونگی (reverse)", "وابستگی، «حذف‌شدن» (FOMO)، حمله‌ی سایبری، «نمایش‌گری» به‌جای «ارتباط»"],
        ],
        col_widths=[5, 11],
    )

    D.h2("۸.۲. شکل و زمینه (Figure and Ground)")
    D.para("«شکل» (figure) = آنچه «در برابر چشم» است (پیش‌زمینه، آنچه می‌بینیم)؛ «زمینه» (ground) = آنچه «در پس‌زمینه/غیرقابل‌بازبینی» افتاده است. در ادراک، ما «شکل» را می‌بینیم اما «زمینه» را نه — «زمینه» تا وقتی «خود را» نشان ندهد، نامرئی است. در تتراد:")
    D.bullet("بهبود (enhance) و بازیابی (retrieve) = «شکل» (آنچه رسانه «نشان» می‌دهد).")
    D.bullet("منسوخ (obsolete) و وارونگی (reverse) = «زمینه» (آنچه رسانه «پنهان» می‌کند).")
    D.para("نکته‌ی تحلیلی: «منسوخ‌سازی» و «وارونگی» تا وقتی که رسانه در حال «بهبود/بازیابی» است، «نامرئی» می‌مانند — به‌همین دلیل، ما معمولاً «اثرات منفی» یک فناوری را «دیر» می‌بینیم. این مفهوم، ابزاری‌ای است برای فهم «چرا اثرات مخربِ رسانه‌ها تا اوجِ گسترششان آشکار نمی‌شوند».")

    D.h2("۸.۳. محیط نامرئی (The Invisible Environment) و تقابل بصری/لامسه")
    D.para("رسانه‌ها «محیط‌هایی» می‌سازند که «خود را نمی‌بینیم» — مثل «آب برای ماهی». ما در «محیطِ رسانه‌ای» زندگی می‌کنیم اما آن را «می‌بینیم» فقط وقتی «خارج» از آن می‌رویم. این، ریشه در مقوله‌ی «شکل/زمینه» است: «محیط» همیشه «زمینه» است، نه «شکل».")
    D.para("در کنار آن، مک‌لوهان تقابل «بصری/لامسه» (optical/haptic) را معرفی می‌کند: «بصری» = خطی، توالی‌دار، فردگرا، کنترل‌پذیر (دنیای چاپ)؛ «لامسه» = هم‌زمان، تجمعی، مشارکتی، «محیطی» (دنیای برقی). عصر الکترونیکی، از «بصری» به «لامسه» برمی‌گردد — و این بازگشت، «دهکده‌ی جهانی» و «تبریزالیزه‌شدن» را می‌سازد.")
    D.callout("تمرین ۸:", "رسانه‌ای (مثلا‌ً «هوش مصنوعی تولیدی» یا «واقعیت مجازی») را انتخاب کنید و تترادِ کامل آن را بنویسید. سپس «شکل/زمینه» را شناسایی کنید: چه چیزی «بازده» (شکل) و چه چیزی «پنهان» (زمینه) است؟")

    D.h2("۸.۴. پیش‌بازخورد (Feedforward) و «وضعیت‌های اسپاستیک»")
    D.para("در کتاب جنگ و صلح در دهکده‌ی جهانی (1968)، مک‌لوهان مفهوم «پیش‌بازخورد» (feedforward) را معرفی کرد — راه‌حلی برای «وضعیت‌های اسپاستیک» (spastic situations). «بازخورد» (feedback)، واکنش به «گذشته» است (واکنش پس‌رونده). اما «پیش‌بازخورد»، «پیش‌بینی و برنامه‌ریزی برای آینده» است — «واکنش پیش‌رونده». در عصر الکترونیکی، «وضعیت‌های اسپاستیک» (بحران‌های پراکنده و هم‌زمان) پدید می‌آیند — مثل «جنگ سرد» یا «بحران‌های مالی جهانی». «پیش‌بازخورد»، راه‌حلی‌ای است برای «مدیریت» این بحران‌ها: به‌جای «واکنش به گذشته»، «پیش‌بینی الگوهای آینده» و «برنامه‌ریزی» برای آن‌ها.")
    D.para("این مفهوم، در «مدیریت بحران» و «هوش مصنوعی پیش‌بینی‌کننده» کاربرد مستقیم دارد. وقتی «الگوریتم‌ها» «رفتار آینده» را «پیش‌بینی» می‌کنند، در واقع «پیش‌بازخورد» به‌کار می‌برند — و این، «مک‌لوهانی» است به معنای دقیق کلمه.")

    D.h2("۸.۵. «نمط» و «طبیعت» (Nomos and Physis) — بُعد فلسفی")
    D.para("مک‌لوهان، در تحلیل‌های دیرهنگام، به تقابل «نمط» (nomos — قانون/عادت/ساختار اجتماعی) و «طبیعت» (physis — ماهیت ذاتی/جسمانی) می‌پرداخت. «نمط»، «قوانینِ نانوشته» جامعه است — «آنچه را که «انگار» طبیعی است، «ساخته» است.» «طبیعت»، «ماهیت ذاتی» بدن و حواس است. رسانه‌ها، «نمط» را تغییر می‌دهند — و این تغییر، «طبیعت» ادراکی ما را باز می‌سازد. این «بُعد فلسفی»، مک‌لوهان را از یک «نظریه‌پرداز رسانه» به یک «فیلسوف فناوری» تبدیل می‌کند — و میراث او را به «فلسفه‌ی فناوری» (philosophy of technology) و «اکولوژی رسانه» متصل می‌کند.")
    D.callout("جمع‌بندی فصل ۸:", "شش مفهوم نظریه‌ای (رسانه پیام است، گسترش بدن، گرم/سرد، مشارکت ادراکی، دهکده‌ی جهانی، تتراد) به‌همراه «شکل/زمینه» و «محیط نامرئی»، «چارچوب تحلیلی» کامل مک‌لوهان را می‌سازند. این چارچوب، ابزاری‌ای است که هر «رسانه‌شناسِ حرفه‌ای» می‌تواند روی هر رسانه‌ای — از تلگراف تا هوش مصنوعی — به‌کار ببرد.")
    D.page_break()
